150: // Interrupt an in-progress call to PollEvent by causing it to return
151: // EventInterrupt.  Note that this function will block until the PollEvent
152: // function has successfully been interrupted.
153: func Interrupt() {
154: 	interrupt_comm <- struct{}{}
155: }
156: 
157: // Finalizes termbox library, should be called after successful initialization
158: // when termbox's functionality isn't required anymore.
159: func Close() {
160: 	if !IsInit {
161: 		return
162: 	}
163: 
164: 	quit <- 1
165: 	out.WriteString(funcs[t_show_cursor])
166: 	out.WriteString(funcs[t_sgr0])
167: 	out.WriteString(funcs[t_clear_screen])
168: 	out.WriteString(funcs[t_exit_ca])
169: 	out.WriteString(funcs[t_exit_keypad])
170: 	out.WriteString(funcs[t_exit_mouse])
171: 	tcsetattr(outfd, orig_tios)
172: 
173: 	out.Close()
174: 	unix.Close(in)
175: 
176: 	// reset the state, so that on next Init() it will work again
177: 	termw = 0
178: 	termh = 0
179: 	input_mode = InputEsc
180: 	out = nil
181: 	in = 0
182: 	lastfg = attr_invalid
183: 	lastbg = attr_invalid
184: 	lastx = coord_invalid
185: 	lasty = coord_invalid
186: 	cursor_x = cursor_hidden
187: 	cursor_y = cursor_hidden
188: 	foreground = ColorDefault
189: 	background = ColorDefault
190: 	IsInit = false
191: }
192: 
193: // Synchronizes the internal back buffer with the terminal.
194: func Flush() error {
195: 	// invalidate cursor position
196: 	lastx = coord_invalid
197: 	lasty = coord_invalid
198: 
199: 	update_size_maybe()
200: 
201: 	for y := 0; y < front_buffer.height; y++ {
202: 		line_offset := y * front_buffer.width
203: 		for x := 0; x < front_buffer.width; {
204: 			cell_offset := line_offset + x
205: 			back := &back_buffer.cells[cell_offset]
206: 			front := &front_buffer.cells[cell_offset]
207: 			if back.Ch < ' ' {
208: 				back.Ch = ' '
209: 			}
210: 			w := runewidth.RuneWidth(back.Ch)
211: 			if w == 0 || w == 2 && runewidth.IsAmbiguousWidth(back.Ch) {
212: 				w = 1
213: 			}
214: 			if *back == *front {
215: 				x += w
216: 				continue
217: 			}
218: 			*front = *back
219: 			send_attr(back.Fg, back.Bg)
220: 
221: 			if w == 2 && x == front_buffer.width-1 {
222: 				// there's not enough space for 2-cells rune,
223: 				// let's just put a space in there
224: 				send_char(x, y, ' ')
225: 			} else {
226: 				send_char(x, y, back.Ch)
227: 				if w == 2 {
228: 					next := cell_offset + 1
229: 					front_buffer.cells[next] = Cell{
230: 						Ch: 0,
231: 						Fg: back.Fg,
232: 						Bg: back.Bg,
233: 					}
234: 				}
235: 			}
236: 			x += w
237: 		}
238: 	}
239: 	if !is_cursor_hidden(cursor_x, cursor_y) {
240: 		write_cursor(cursor_x, cursor_y)
241: 	}
242: 	return flush()
243: }
244: 
245: // Sets the position of the cursor. See also HideCursor().
246: func SetCursor(x, y int) {
247: 	if is_cursor_hidden(cursor_x, cursor_y) && !is_cursor_hidden(x, y) {
248: 		outbuf.WriteString(funcs[t_show_cursor])
249: 	}
250: 
251: 	if !is_cursor_hidden(cursor_x, cursor_y) && is_cursor_hidden(x, y) {
252: 		outbuf.WriteString(funcs[t_hide_cursor])
253: 	}
254: 
255: 	cursor_x, cursor_y = x, y
256: 	if !is_cursor_hidden(cursor_x, cursor_y) {
257: 		write_cursor(cursor_x, cursor_y)
258: 	}
259: }
260: 
261: // The shortcut for SetCursor(-1, -1).
262: func HideCursor() {
263: 	SetCursor(cursor_hidden, cursor_hidden)
264: }
265: 
266: // Changes cell's parameters in the internal back buffer at the specified
267: // position.
268: func SetCell(x, y int, ch rune, fg, bg Attribute) {
269: 	if x < 0 || x >= back_buffer.width {
270: 		return
271: 	}
272: 	if y < 0 || y >= back_buffer.height {
273: 		return
274: 	}
275: 
276: 	back_buffer.cells[y*back_buffer.width+x] = Cell{ch, fg, bg}
277: }
278: 
279: // Returns the specified cell from the internal back buffer.
280: // Returns an empty cell if coordinates are out of bounds.
281: func GetCell(x, y int) Cell {
282: 	if x < 0 || x >= back_buffer.width || y < 0 || y >= back_buffer.height {
283: 		return Cell{}
284: 	}
285: 	return back_buffer.cells[y*back_buffer.width+x]
286: }
287: 
288: // Changes cell's character (rune) in the internal back buffer at the
289: // specified position.
290: func SetChar(x, y int, ch rune) {
291: 	if x < 0 || x >= back_buffer.width {
292: 		return
293: 	}
294: 	if y < 0 || y >= back_buffer.height {
295: 		return
296: 	}
297: 
298: 	back_buffer.cells[y*back_buffer.width+x].Ch = ch
299: }
300: 
301: // Changes cell's foreground attributes in the internal back buffer at
302: // the specified position.
303: func SetFg(x, y int, fg Attribute) {
304: 	if x < 0 || x >= back_buffer.width {
305: 		return
306: 	}
307: 	if y < 0 || y >= back_buffer.height {
308: 		return
309: 	}
310: 
311: 	back_buffer.cells[y*back_buffer.width+x].Fg = fg
312: }
313: 
314: // Changes cell's background attributes in the internal back buffer at
315: // the specified position.
316: func SetBg(x, y int, bg Attribute) {
317: 	if x < 0 || x >= back_buffer.width {
318: 		return
319: 	}
320: 	if y < 0 || y >= back_buffer.height {
321: 		return
322: 	}
323: 
324: 	back_buffer.cells[y*back_buffer.width+x].Bg = bg
325: }
326: 
327: // Returns a slice into the termbox's back buffer. You can get its dimensions
328: // using 'Size' function. The slice remains valid as long as no 'Clear' or
329: // 'Flush' function calls were made after call to this function.
330: func CellBuffer() []Cell {
331: 	return back_buffer.cells
332: }
333: 
334: // After getting a raw event from PollRawEvent function call, you can parse it
335: // again into an ordinary one using termbox logic. That is parse an event as
336: // termbox would do it. Returned event in addition to usual Event struct fields
337: // sets N field to the amount of bytes used within 'data' slice. If the length
338: // of 'data' slice is zero or event cannot be parsed for some other reason, the
339: // function will return a special event type: EventNone.
340: //
341: // IMPORTANT: EventNone may contain a non-zero N, which means you should skip
342: // these bytes, because termbox cannot recognize them.
343: //
344: // NOTE: This API is experimental and may change in future.
345: func ParseEvent(data []byte) Event {
346: 	event := Event{Type: EventKey}
347: 	status := extract_event(data, &event, false)
348: 	if status != event_extracted {
349: 		return Event{Type: EventNone, N: event.N}
350: 	}
351: 	return event
352: }
353: 
354: // Wait for an event and return it. This is a blocking function call. Instead
355: // of EventKey and EventMouse it returns EventRaw events. Raw event is written
356: // into `data` slice and Event's N field is set to the amount of bytes written.
357: // The minimum required length of the 'data' slice is 1. This requirement may
358: // vary on different platforms.
359: //
360: // NOTE: This API is experimental and may change in future.
361: func PollRawEvent(data []byte) Event {
362: 	if len(data) == 0 {
363: 		panic("len(data) >= 1 is a requirement")
364: 	}
365: 
366: 	var event Event
367: 	if extract_raw_event(data, &event) {
368: 		return event
369: 	}
370: 
371: 	for {
372: 		select {
373: 		case ev := <-input_comm:
374: 			if ev.err != nil {
375: 				return Event{Type: EventError, Err: ev.err}
376: 			}
377: 
378: 			inbuf = append(inbuf, ev.data...)
379: 			input_comm <- ev
380: 			if extract_raw_event(data, &event) {
381: 				return event
382: 			}
383: 		case <-interrupt_comm:
384: 			event.Type = EventInterrupt
385: 			return event
386: 
387: 		case <-sigwinch:
388: 			event.Type = EventResize
389: 			event.Width, event.Height = get_term_size(outfd)
390: 			return event
391: 		}
392: 	}
393: }
394: 
395: // Wait for an event and return it. This is a blocking function call.
396: func PollEvent() Event {
397: 	// Constant governing macOS specific behavior. See https://github.com/nsf/termbox-go/issues/132
398: 	// This is an arbitrary delay which hopefully will be enough time for any lagging
399: 	// partial escape sequences to come through.
400: 	const esc_wait_delay = 100 * time.Millisecond
401: 
402: 	var event Event
403: 	var esc_wait_timer *time.Timer
404: 	var esc_timeout <-chan time.Time
405: 
406: 	// try to extract event from input buffer, return on success
407: 	event.Type = EventKey
408: 	status := extract_event(inbuf, &event, true)
409: 	if event.N != 0 {
410: 		copy(inbuf, inbuf[event.N:])
411: 		inbuf = inbuf[:len(inbuf)-event.N]
412: 	}
413: 	switch status {
414: 	case event_extracted:
415: 		return event
416: 	case esc_wait:
417: 		esc_wait_timer = time.NewTimer(esc_wait_delay)
418: 		esc_timeout = esc_wait_timer.C
419: 	}
420: 
421: 	for {
422: 		select {
423: 		case ev := <-input_comm:
424: 			if esc_wait_timer != nil {
425: 				if !esc_wait_timer.Stop() {
426: 					<-esc_wait_timer.C
427: 				}
428: 				esc_wait_timer = nil
429: 			}
430: 
431: 			if ev.err != nil {
432: 				return Event{Type: EventError, Err: ev.err}
433: 			}
434: 
435: 			inbuf = append(inbuf, ev.data...)
436: 			input_comm <- ev
437: 			status := extract_event(inbuf, &event, true)
438: 			if event.N != 0 {
439: 				copy(inbuf, inbuf[event.N:])
440: 				inbuf = inbuf[:len(inbuf)-event.N]
441: 			}
442: 			switch status {
443: 			case event_extracted:
444: 				return event
445: 			case esc_wait:
446: 				esc_wait_timer = time.NewTimer(esc_wait_delay)
447: 				esc_timeout = esc_wait_timer.C
448: 			}
449: 		case <-esc_timeout:
450: 			esc_wait_timer = nil
451: 
452: 			status := extract_event(inbuf, &event, false)
453: 			if event.N != 0 {
454: 				copy(inbuf, inbuf[event.N:])
455: 				inbuf = inbuf[:len(inbuf)-event.N]
456: 			}
457: 			if status == event_extracted {
458: 				return event
459: 			}
460: 		case <-interrupt_comm:
461: 			event.Type = EventInterrupt
462: 			return event
463: 
464: 		case <-sigwinch:
465: 			event.Type = EventResize
466: 			event.Width, event.Height = get_term_size(outfd)
467: 			return event
468: 		}
469: 	}
470: }
471: 
472: // Returns the size of the internal back buffer (which is mostly the same as
473: // terminal's window size in characters). But it doesn't always match the size
474: // of the terminal window, after the terminal size has changed, the internal
475: // back buffer will get in sync only after Clear or Flush function calls.
476: func Size() (width int, height int) {
477: 	return termw, termh
478: }
479: 
480: // Clears the internal back buffer.
481: func Clear(fg, bg Attribute) error {
482: 	foreground, background = fg, bg
483: 	err := update_size_maybe()
484: 	back_buffer.clear()
485: 	return err
486: }
487: 
488: // Sets termbox input mode. Termbox has two input modes:
489: //
490: // 1. Esc input mode. When ESC sequence is in the buffer and it doesn't match
491: // any known sequence. ESC means KeyEsc. This is the default input mode.
492: //
493: // 2. Alt input mode. When ESC sequence is in the buffer and it doesn't match
494: // any known sequence. ESC enables ModAlt modifier for the next keyboard event.
495: //
496: // Both input modes can be OR'ed with Mouse mode. Setting Mouse mode bit up will
497: // enable mouse button press/release and drag events.
498: //
499: // If 'mode' is InputCurrent, returns the current input mode. See also Input*
500: // constants.
501: func SetInputMode(mode InputMode) InputMode {
502: 	if mode == InputCurrent {
503: 		return input_mode
504: 	}
505: 	if mode&(InputEsc|InputAlt) == 0 {
506: 		mode |= InputEsc
507: 	}
508: 	if mode&(InputEsc|InputAlt) == InputEsc|InputAlt {
509: 		mode &^= InputAlt
510: 	}
511: 	if mode&InputMouse != 0 {
512: 		out.WriteString(funcs[t_enter_mouse])
513: 	} else {
514: 		out.WriteString(funcs[t_exit_mouse])
515: 	}
516: 
517: 	input_mode = mode
518: 	return input_mode
519: }
520: 
521: // Sets the termbox output mode. Termbox has four output options:
522: //
523: //  1. OutputNormal => [1..8]
524: //     This mode provides 8 different colors:
525: //     black, red, green, yellow, blue, magenta, cyan, white
526: //     Shortcut: ColorBlack, ColorRed, ...
527: //     Attributes: AttrBold, AttrUnderline, AttrReverse
528: //
529: //     Example usage:
530: //     SetCell(x, y, '@', ColorBlack | AttrBold, ColorRed);
531: //
532: //  2. Output256 => [1..256]
533: //     In this mode you can leverage the 256 terminal mode:
534: //     0x01 - 0x08: the 8 colors as in OutputNormal
535: //     0x09 - 0x10: Color* | AttrBold
