568: func append_diff_line(y int) int {
569: 	n := 0
570: 	for x := 0; x < front_buffer.width; {
571: 		cell_offset := y*front_buffer.width + x
572: 		back := &back_buffer.cells[cell_offset]
573: 		front := &front_buffer.cells[cell_offset]
574: 		attr, char := cell_to_char_info(*back)
575: 		charbuf = append(charbuf, char_info{attr: attr, char: char[0]})
576: 		*front = *back
577: 		n++
578: 		w := runewidth.RuneWidth(back.Ch)
579: 		if w == 0 || w == 2 && runewidth.IsAmbiguousWidth(back.Ch) {
580: 			w = 1
581: 		}
582: 		x += w
583: 		// If not CJK, fill trailing space with whitespace
584: 		if !is_cjk && w == 2 {
585: 			charbuf = append(charbuf, char_info{attr: attr, char: ' '})
586: 		}
587: 	}
588: 	return n
589: }
