591: // compares 'back_buffer' with 'front_buffer' and prepares all changes in the form of
592: // 'diff_msg's in the 'diff_buf'
593: func prepare_diff_messages() {
594: 	// clear buffers
595: 	diffbuf = diffbuf[:0]
596: 	charbuf = charbuf[:0]
597: 
598: 	var diff diff_msg
599: 	gbeg := 0
600: 	for y := 0; y < front_buffer.height; y++ {
601: 		same := true
602: 		line_offset := y * front_buffer.width
603: 		for x := 0; x < front_buffer.width; x++ {
604: 			cell_offset := line_offset + x
605: 			back := &back_buffer.cells[cell_offset]
606: 			front := &front_buffer.cells[cell_offset]
607: 			if *back != *front {
608: 				same = false
609: 				break
610: 			}
611: 		}
612: 		if same && diff.lines > 0 {
613: 			diffbuf = append(diffbuf, diff)
614: 			diff = diff_msg{}
615: 		}
616: 		if !same {
617: 			beg := len(charbuf)
618: 			end := beg + append_diff_line(y)
619: 			if diff.lines == 0 {
620: 				diff.pos = short(y)
621: 				gbeg = beg
622: 			}
623: 			diff.lines++
624: 			diff.chars = charbuf[gbeg:end]
625: 		}
626: 	}
627: 	if diff.lines > 0 {
628: 		diffbuf = append(diffbuf, diff)
629: 		diff = diff_msg{}
630: 	}
631: }
