            "ecosystem": {"type": "string", "description": "LANGUAGE ecosystem only: cpp/c/python/java/nodejs/rust/go/dotnet/other. Use 'other' for non-language deps (data files, generic tools); do NOT put role values like 'tool'/'data' here — a dependency's build-tool nature belongs in scope:build."},
            "registry_name": {"type": ["string", "null"],
              "description": "model: 该依赖的规范/注册表包名（PyPI/npm/Maven artifact/crate；或 CMake find_package 的真实包名），当 `name` 是别名/接口名/缩写时填它，便于按名关联到已分析库。不确定则 null。"},
            "source_repo": {"type": ["string", "null"],
