    "native_api": {
      "type": "object",
      "description": "Dimension 7 — MODEL (skill: native-api-analysis).",
      "properties": {
        "summary": {"type": "string"},
        "groups": {"type": "array", "items": {
          "type": "object",
          "required": ["type"],
          "properties": {
            "type": {"type": "string",
              "description": "API family, e.g. win32, posix, cpp_stl, python_stdlib, java_std, node_core, syscall, ctypes_ffi, jni, opengl, directx, arch_simd"},
            "category": {"type": "string",
              "enum": ["standard", "platform", "system", "ffi", "hardware"],
              "description": "按可移植性分类。standard=语言标准库/运行时,到处可用(C++ STL、Python stdlib、JDK标准包、Node内置); platform=某OS专有,换平台即没有(Win32 与 POSIX-only 如 mmap/fork/epoll/<unistd.h> 都属此,再用 platform 字段标 windows/posix/macos); system=内核/系统调用层(裸 syscall、ioctl、/proc、/sys、注册表、WMI、设备); ffi=互操作桥(ctypes/cffi/JNI/N-API); hardware=GPU/SIMD/加速器"},
            "platform": {"type": "string",
              "enum": ["windows", "posix", "linux", "macos", "portable", "unknown"],
              "description": "该组 API 所属平台；portable=跨平台(标准库)"},
            "apis": {"type": "array",
              "description": "逐个具体 API（代表性，非穷举）",
              "items": {
                "type": "object",
                "required": ["name"],
                "properties": {
                  "name": {"type": "string", "description": "单个具体 API/符号名（如 mmap、CreateFileMapping、std::filesystem）。不要把多个调用并进一个 name（如 'mmap / munmap'），否则 count 失去意义"},
                  "purpose": {"type": "string", "description": "中文：该 API 的作用"},
                  "count": {"type": "integer", "description": "调用次数/出现次数（代表性近似，grep -c 或 codegraph callers）"},
                  "evidence": {"type": "array", "items": {"type": "string"},
                    "description": "调用位置 file:line（代表性 1-3 处）"},
                  "conditional": {"type": "boolean", "description": "是否被 #ifdef / 平台条件守卫"}}}},
            "evidence": {"type": "array", "items": {"type": "string"},
              "description": "group-level files / includes (optional; prefer per-api evidence)"}}}},
        "dynamic_libraries": {
          "type": "array",
          "description": "Libraries loaded at RUNTIME via dynamic loading (not declared in package manifests). Model resolves the loaded library name and infers its purpose.",
          "items": {
            "type": "object",
            "required": ["name"],
            "properties": {
              "name": {"type": "string", "description": "loaded library name, e.g. 'libssl.so', 'kernel32.dll', 'libcudart' (keep as written; '<dynamic>' if computed at runtime)"},
              "mechanism": {"type": "string",
                "description": "how it is loaded: dlopen / LoadLibrary / ctypes.CDLL / ctypes.WinDLL / cffi.dlopen / JNI System.loadLibrary / node N-API addon"},
              "acquisition": {"type": "string",
                "description": "OPEN vocab — HOW the loaded lib is obtained: self_build (built from THIS repo, e.g. a CFFI/JNI/SWIG wrapper), system (external/OS-provided), bundled (shipped in repo), third_party, unknown"},
              "source": {"type": "string", "description": "中文：是什么库 / 出处（身份与来源），如「本仓 MinimalLib 的 CFFI 构建产物」「外部专有 DLL，需 COMBICHEM_ROOT 提供」"},
              "description": {"type": "string", "description": "model-inferred purpose of the loaded library, 简体中文"},
              "optional": {"type": "boolean", "description": "true if load failure is handled gracefully (feature is optional)"},
              "evidence": {"type": "array", "items": {"type": "string"},
                "description": "file + call site"}}}},
        "platform_dependence": {"type": "string",
          "enum": ["cross-platform", "windows-only", "posix-only", "mixed", "unknown"]}
      }
    },

